// RunEncounter is the resolver for the runEncounter field.
func (r *campaignMutationResolver) RunEncounter(ctx context.Context, obj *model.CampaignMutation, encounterID string) ([]*model.CampaignMonster, error) {
	encounter, campaign, _, err := r.loadEncounter(ctx, encounterID)
	if err != nil {
		return nil, err
	}

	var monsters []*model.CampaignMonster
	err = r.inTransaction(ctx, func(queries *db.Queries) error {
		entries, err := queries.SelectEncounterMonstersByEncounters(ctx, []pgtype.UUID{encounter.ID})
		if err != nil {
			return fmt.Errorf("failed to load encounter monsters: %w", err)
		}

		existing, err := queries.SelectCampaignMonsterNames(ctx, campaign.ID)
		if err != nil {
			return fmt.Errorf("failed to load monster names for campaign with ID '%s': %w", campaign.ID.String(), err)
		}

		for _, entry := range entries {
			var stats models.MonsterStatBlock
			if err := json.Unmarshal(entry.StatBlock, &stats); err != nil {
				return fmt.Errorf("failed to read encounter monster '%s': %w", entry.ID.String(), err)
			}

			names := models.NextMonsterNames(stats.Name, int(entry.Count), existing)
			existing = append(existing, names...)
			for _, name := range names {
				row, err := queries.InsertCampaignMonster(ctx, db.InsertCampaignMonsterParams{
					CampaignID:      campaign.ID,
					CustomMonsterID: entry.CustomMonsterID,
					EncounterID:     encounter.ID,
					Hp:              entry.MaxHp,
					Name:            name,
					SourceKey:       entry.SourceKey,
					StatBlock:       entry.StatBlock,
				})
				if err != nil {
					return fmt.Errorf("failed to put a monster into play: %w", err)
				}
				m, err := r.campaignMonsterObject(&row)
				if err != nil {
					return err
				}
				monsters = append(monsters, m)
			}
		}

		return nil
	})
	if err != nil {
		return nil, err
	}

	if monsters == nil {
		monsters = []*model.CampaignMonster{}
	}

	return monsters, nil
}

