	if revealed && !portent.RevealedAt.Valid {
		logCampaignActivity(ctx, r.DbPool, campaign.ID, user, fmt.Sprintf("The GM revealed a grim portent of %s: %s", danger.Name, portent.Text))
	}

	return r.dangerByID(ctx, queries, danger.ID)
